-- 中央机构第一批：2022-10-16 至 2026-10-29
-- 由 scripts/build_central.py 生成；JSON 演示数据同步落库。
CREATE TABLE IF NOT EXISTS polvis.central_institutions (
  id text PRIMARY KEY, parent_id text, team text NOT NULL,
  group_type text NOT NULL, institution_type text NOT NULL,
  name text NOT NULL, short_name text, institution_rank text,
  level integer, sort_order integer
);
CREATE TABLE IF NOT EXISTS polvis.central_committee_terms (
  ordinal integer PRIMARY KEY, label text, start_date date, end_date date
);
CREATE TABLE IF NOT EXISTS polvis.central_committee_memberships (
  id bigserial PRIMARY KEY, officer_name text NOT NULL, term integer NOT NULL,
  member_type text NOT NULL, start_date date, end_date date,
  status text, status_date date,
  UNIQUE (officer_name, term, member_type)
);
DELETE FROM polvis.central_institutions;
DELETE FROM polvis.central_committee_terms;
DELETE FROM polvis.central_committee_memberships;
